// Inlines Leaflet's dist JS/CSS into components/generated/leaflet_assets.ts so the
// map page can be built as one self-contained HTML string (Metro can't import
// .js files as text). Re-run only when upgrading the `leaflet` devDependency:
//   node scripts/gen_leaflet_assets.js
const fs = require('fs')
const path = require('path')

const root = path.resolve(__dirname, '..')
const dist = path.join(root, 'node_modules', 'leaflet', 'dist')
const outFile = path.join(root, 'components', 'generated', 'leaflet_assets.ts')

const read = (name) =>
  fs
    .readFileSync(path.join(dist, name), 'utf8')
    .replace(/\n?\/\/# sourceMappingURL=.*$/m, '')
    .trimEnd()

const js = read('leaflet.js')
const css = read('leaflet.css')
// The strings are embedded in <script>/<style> tags; a closing tag inside would break the page.
if (/<\/script/i.test(js) || /<\/style/i.test(css)) {
  throw new Error('Leaflet assets contain a closing tag; cannot inline safely')
}
const version = require(path.join(root, 'node_modules', 'leaflet', 'package.json')).version

const out = `// GENERATED by scripts/gen_leaflet_assets.js from leaflet@${version} — do not edit by hand.
/* eslint-disable */
export const LEAFLET_VERSION = ${JSON.stringify(version)}
export const LEAFLET_JS = ${JSON.stringify(js)}
export const LEAFLET_CSS = ${JSON.stringify(css)}
`

fs.mkdirSync(path.dirname(outFile), { recursive: true })
fs.writeFileSync(outFile, out)
console.log(`Wrote ${path.relative(root, outFile)} (${out.length} bytes)`)
